function updateHUD(){let m=Math.round(state.mood);$('#moodValue').textContent=m+'%';$('#moodBar').style.width=m+'%';$('#shoeValue').textContent=state.shoe<8?'KULLANILAMAZ':state.shoe<40?'YIPRANMIŞ':state.shoe<70?'ISLAK':'SAĞLAM';$('#shoeBar').style.width=state.shoe+'%';$('#shoeBar').style.background=state.shoe<35?'#d97e7e':state.shoe<70?'#e1ba7d':'#80c4b8';$('#shoeTag').textContent='✦ '+state.shoeName;$('#outfitTag').textContent=state.wardrobe.shirt||'Beyaz gömlek';$('#missionBar').style.width=Math.min(100,state.missionProgress/3*100)+'%';$('#missionText').textContent=state.mission===0?`Sahil yolunu kontrol et · ${Math.min(3,state.missionProgress)} / 3`:`${state.eventsHandled} olaya müdahale edildi`;$('#ownedCount').textContent=`Koleksiyonun: ${state.owned.size} parça`}
function targetEvent(){return eventSpots[state.activeEvent%eventSpots.length]}
function activateEvent(){let e=targetEvent();let obj=e.npc;if(e.type==='Lost child'){obj=civilians[3]}else if(e.type==='Beach call'){obj=civilians[7]}else if(e.type==='Lost wallet'){obj=civilians[10]}else{obj=e.npc}
 obj.group.visible=true;state.activeTarget=obj;state.activeIncident=e;let mark=sphere(scene,e.x,2.4,e.z,.18,.18,.18,M.yellow);mark.userData.eventMark=true;if(state.eventMark)scene.remove(state.eventMark);state.eventMark=mark;toast('YARDIM ÇAĞRISI · '+e.label);setObjective(e.label,`${e.detail} · <kbd>E</kbd>`);changeMood(-5);}
