function wearItem(item){state.wardrobe={...item};state.owned.add(item.name);if(item.kind==='heel'||item.kind==='flat'){state.shoeName=item.name;state.shoeType=item.kind;state.heel=item.heel||0;state.shoe=100;state.wet=false;for(let s of [-1,1]){avatar.children.filter(c=>c.position.y<.2&&c.position.x*s>0).slice(-1)[0]?.material?.color?.set(item.color)}toast(item.kind==='flat'?`${item.name} giyildi. Ayakların rahatlayacak.`:`${item.name} hazır. Şıklık tamam, dikkatli adımlar!`);$('#fitName').textContent=item.name}else if(item.kind==='shirt'){state.wardrobe.shirt=item.name;toast(`${item.name} seçildi. Üniformana çok yakıştı.`)}else if(item.kind==='tights'){state.wardrobe.tights=item.name;toast(`${item.name} giyildi. Görünüm güncellendi.`)}updateHUD()}
