addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e'||k===' ')interact();if(k==='b')$('#wardrobePanel').classList.toggle('open');if(k==='m')$('#mapPanel').classList.toggle('open');if(k==='escape')$('#pauseBtn').click()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
